// Activity Selection - maximize non-overlapping intervals (sort by end time)
function maxActivities(intervals) {
  intervals.sort((a, b) => a[1] - b[1]); // sort by END time
  let count = 1;
  let lastEnd = intervals[0][1];

  for (let i = 1; i < intervals.length; i++) {
    if (intervals[i][0] >= lastEnd) { // starts at or after last end
      count++;
      lastEnd = intervals[i][1];
    }
  }
  return count;
}

// Jump Game - greedy maxReach scan
function canJump(nums) {
  let maxReach = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > maxReach) return false; // can't reach this index
    maxReach = Math.max(maxReach, i + nums[i]);
  }
  return true;
}

// Gas Station - find valid start using running tank reset
function canCompleteCircuit(gas, cost) {
  let totalTank = 0, tank = 0, start = 0;
  for (let i = 0; i < gas.length; i++) {
    const net = gas[i] - cost[i];
    totalTank += net;
    tank += net;
    if (tank < 0) { // failed from current start - reset
      start = i + 1;
      tank = 0;
    }
  }
  return totalTank >= 0 ? start : -1;
}
